import math

def is_perfect_cube(n):
    if n == 0:
        return True
    sign = 1 if n > 0 else -1
    abs_n = abs(n)
    # Use integer approximation of cube root
    cbrt_approx = round(abs_n**(1/3))

    # Check values around the approximation due to floating point precision
    for c in range(cbrt_approx - 2, cbrt_approx + 3):
        if c**3 == abs_n:
            return True

    return False

def check_solution(y):
    # y = x + 3, E(x) = y^2 * (8y - 65)
    if y == 0:
        return 0, True

    expr = y**2 * (8*y - 65)
    if is_perfect_cube(expr):
        cbrt = round(expr**(1/3))
        if cbrt**3 == expr:
            return cbrt, True
    return None, False

# Check values satisfying y mod 7 = 0, 1, 2, focusing outside [-30, 30]
# Test positive values y >= 31
y_candidates_pos = [y for y in range(31, 61) if y % 7 in [0, 1, 2]]

# Test negative values y <= -31
y_candidates_neg = [y for y in range(-61, -31) if y % 7 in [0, 1, 2]]

print("Testing positive candidates (y >= 31):")
for y in y_candidates_pos:
    cbrt, found = check_solution(y)
    if found:
